//==========================================================================
// tb_nice_adapter.v - self-checking command/protocol testbench
//
// The command stream is generated by model/gen_vectors.py into
// vectors/gen/nice_seq.hex, so the same style (file-driven, independently
// scored) is used by every testbench in this repository.
//
// One legal sequence is interleaved with five classes of illegal sequence.
// An illegal request must be REJECTED (rsp_err=1, rsp_data=DEAD_BEEF) and
// must not corrupt state: the legal MAC/READ pair after the rejections still
// returns the Python-computed INT8 result.
//
// This adapter is NICE-STYLE only, not the official NICE implementation.
//==========================================================================
`timescale 1ns/1ps
`default_nettype none

module tb_nice_adapter;

    reg         clk = 1'b0;
    reg         rst_n = 1'b0;
    reg         req_valid = 1'b0;
    reg  [31:0] req_inst = 32'h0;
    reg  [31:0] req_rs1  = 32'h0;
    reg  [31:0] req_rs2  = 32'h0;
    reg         rsp_ready = 1'b1;

    wire        req_ready, rsp_valid, rsp_err;
    wire [31:0] rsp_data;

    nice_adapter #(.N_LANE(8), .IN_W(8), .ACC_W(32), .R32_W(16)) u_dut (
        .clk            (clk),
        .rst_n          (rst_n),
        .nice_req_valid (req_valid),
        .nice_req_ready (req_ready),
        .nice_req_inst  (req_inst),
        .nice_req_rs1   (req_rs1),
        .nice_req_rs2   (req_rs2),
        .nice_rsp_valid (rsp_valid),
        .nice_rsp_ready (rsp_ready),
        .nice_rsp_data  (rsp_data),
        .nice_rsp_err   (rsp_err),
        .dbg_acc        ()
    );

    always #5 clk = ~clk;

    localparam [6:0]  F_READ = 7'h06;
    localparam [31:0] ERR_WORD = 32'hDEAD_BEEF;
    localparam integer N_VEC = 13;

    integer dfd, vfd, gfd, code, i, errors, npts;
    reg [6:0]  vf;
    reg [31:0] vr1, vr2, vdata;
    reg        verr;
    reg [7:0]  exp_y;
    reg        exp_sat;
    reg [31:0] dummy0, dummy1, dummy2, dummy3;
    reg [15:0] dummy4, dummy5;
    reg [31:0] exp_read_data;
    reg [31:0] expected_data;

    initial begin
        gfd = $fopen("vectors/gen/nice_expect.hex", "r");
        vfd = $fopen("vectors/gen/nice_seq.hex", "r");
        dfd = $fopen("results/dump_nice_adapter.csv", "w");
        if (gfd == 0 || vfd == 0 || dfd == 0) begin
            $display("RESULT tb_nice_adapter FAIL (cannot open vectors/results)");
            $finish;
        end
        code = $fscanf(gfd, "%h %h %h %h %h %h %h %h",
                       exp_y, exp_sat, dummy0, dummy1,
                       dummy2, dummy3, dummy4, dummy5);
        if (code != 8) begin
            $display("RESULT tb_nice_adapter FAIL (bad golden file)");
            $finish;
        end
        $fclose(gfd);
        $fdisplay(dfd, "test,index,expected,actual");
        exp_read_data = {{24{exp_y[7]}}, exp_y};

        errors = 0;
        npts   = 0;

        @(negedge clk);
        @(negedge clk);
        @(negedge clk);
        rst_n = 1'b1;
        @(negedge clk);

        for (i = 0; i < N_VEC; i = i + 1) begin
            code = $fscanf(vfd, "%h %h %h %h %h", vf, vr1, vr2, verr, vdata);
            if (code != 5) begin
                $display("RESULT tb_nice_adapter FAIL (short command file at %0d)", i);
                $fclose(vfd); $fclose(dfd); $finish;
            end

            // A legal READ returns the Python-computed result, cross-checking
            // the two golden files instead of trusting the command file.
            if ((vf == F_READ) && (verr == 1'b0)) begin
                expected_data = exp_read_data;
            end else if (verr) begin
                expected_data = ERR_WORD;
            end else begin
                expected_data = vdata;
            end

            @(negedge clk);
            req_valid = 1'b1;
            req_inst  = {vf, 25'b0};
            req_rs1   = vr1;
            req_rs2   = vr2;

            @(posedge clk);
            #1;
            if (rsp_valid !== 1'b1) begin
                $display("  no response cmd=%0d funct7=%h", i, vf);
                errors = errors + 1;
            end
            if (rsp_err !== verr) begin
                $display("  err mismatch cmd=%0d funct7=%h exp=%b got=%b",
                         i, vf, verr, rsp_err);
                errors = errors + 1;
            end
            if (rsp_data !== expected_data) begin
                $display("  data mismatch cmd=%0d funct7=%h exp=%h got=%h",
                         i, vf, expected_data, rsp_data);
                errors = errors + 1;
            end
            $fdisplay(dfd, "nice_adapter,%0d,%h,%h", i,
                      {verr, expected_data}, {rsp_err, rsp_data});
            npts  = npts + 1;
            req_valid = 1'b0;

            @(posedge clk);
            #1;
        end

        $fclose(vfd);
        $fclose(dfd);
        $display("RESULT tb_nice_adapter  commands=%0d mismatches=%0d", npts, errors);
        if (errors == 0) $display("RESULT tb_nice_adapter PASS");
        else             $display("RESULT tb_nice_adapter FAIL");
        $finish;
    end

endmodule

`default_nettype wire
